import{_ as e,o as t,c as o,a2 as n}from"./chunks/framework.F7eQ-ohH.js";const r="/bzygq/assets/3b3a7a7dba2843b8a03546d014f6996e.BFC_aitP.png",d="/bzygq/assets/4b48bb4a6ef0425db0f61d36a7651b66.Cz2FSmBl.png",u=JSON.parse('{"title":"06、MySQL 事务：ACID、并发问题与隔离级别","description":"","frontmatter":{},"headers":[],"relativePath":"Java面试问题汇总/MySQL/06、MySQL 事务：ACID、并发问题与隔离级别.md","filePath":"Java面试问题汇总/MySQL/06、MySQL 事务：ACID、并发问题与隔离级别.md","lastUpdated":1788929995000}'),i={name:"Java面试问题汇总/MySQL/06、MySQL 事务：ACID、并发问题与隔离级别.md"};function l(p,a,h,c,s,_){return t(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="_06、mysql-事务-acid、并发问题与隔离级别" tabindex="-1">06、MySQL 事务：ACID、并发问题与隔离级别 <a class="header-anchor" href="#_06、mysql-事务-acid、并发问题与隔离级别" aria-label="Permalink to &quot;06、MySQL 事务：ACID、并发问题与隔离级别&quot;">​</a></h1><p>事务（Transaction）是数据库把一组操作组织成一个逻辑工作单元的机制。它的核心目标不是让单条 SQL 更快，而是在多条 SQL 组合执行、并发访问和异常失败的情况下，仍然让数据保持正确。MySQL InnoDB 通过 undo log、redo log、锁和 MVCC 共同实现事务能力，其中 ACID 是事务性质，隔离级别是并发可见性策略，Read View 和 next-key lock 则是理解 InnoDB 实现细节的关键。</p><p>以转账为例，A 给 B 转 100 元至少包含两步：A 扣减 100，B 增加 100。任何一步单独成功都不是正确结果，只有两步整体成功才算业务完成。事务就是把这类必须共同成立的操作包起来，使系统可以在失败时回滚，在成功后持久保存，并在并发环境中控制不同事务之间的影响。</p><h2 id="一、事务为什么会出现" tabindex="-1">一、事务为什么会出现 <a class="header-anchor" href="#一、事务为什么会出现" aria-label="Permalink to &quot;一、事务为什么会出现&quot;">​</a></h2><p>如果数据库只有单用户、单语句、无故障场景，事务的价值并不明显。但真实系统里，一个订单创建可能同时写订单表、库存表、支付流水和优惠券记录；一个账户扣款可能伴随余额变更、流水生成和风控状态更新。任何一步失败，都可能造成业务状态不一致。</p><p>事务出现的原因可以概括为三点。第一，复杂业务需要“多步操作整体成功”。第二，系统可能随时发生异常，例如 SQL 报错、进程崩溃、机器断电。第三，并发事务会交叉读写同一批数据，如果不控制可见性和加锁范围，就会出现脏读、不可重复读、幻读、丢失更新等问题。</p><p><img src="'+r+'" alt="images/mysql-06-transaction-mvcc.png"></p><p>images/mysql-06-transaction-mvcc.png</p><p>这张图把事务实现拆成两条线：写路径依赖 undo 和 redo，保证可回滚与可恢复；读路径依赖 Read View 和版本链，决定当前事务能看到哪个历史版本。隔离级别本质上就是在“读到多新的数据”和“允许多少并发”之间做取舍。</p><h2 id="二、acid-四个性质如何落到-innodb" tabindex="-1">二、ACID 四个性质如何落到 InnoDB <a class="header-anchor" href="#二、acid-四个性质如何落到-innodb" aria-label="Permalink to &quot;二、ACID 四个性质如何落到 InnoDB&quot;">​</a></h2><p>ACID 是 Atomicity、Consistency、Isolation、Durability 的缩写。它不是四个互相独立的组件，而是数据库、日志、锁、约束和业务规则共同形成的事务语义。</p><h3 id="_1-原子性-要么全部成功-要么全部撤销" tabindex="-1">1. 原子性：要么全部成功，要么全部撤销 <a class="header-anchor" href="#_1-原子性-要么全部成功-要么全部撤销" aria-label="Permalink to &quot;1\\. 原子性：要么全部成功，要么全部撤销&quot;">​</a></h3><p>原子性要求事务中的操作不可再分割。InnoDB 主要依靠 undo log 支撑回滚：事务修改数据前会记录旧版本，如果后续失败或用户执行 ROLLBACK，就可以根据 undo 撤销已经完成的修改。保存点 SAVEPOINT 也是基于类似思路，让事务可以回滚到中间位置。</p><p>原子性关注的是“失败后如何撤销”，不是“提交后如何不丢”。很多同学会把 undo 和 redo 混在一起：undo 用于回滚，redo 用于崩溃恢复，两者方向正好相反。</p><h3 id="_2-一致性-从一个正确状态到另一个正确状态" tabindex="-1">2. 一致性：从一个正确状态到另一个正确状态 <a class="header-anchor" href="#_2-一致性-从一个正确状态到另一个正确状态" aria-label="Permalink to &quot;2\\. 一致性：从一个正确状态到另一个正确状态&quot;">​</a></h3><p>一致性表示事务执行前后，数据都满足业务规则和数据库约束。它不是某一个日志单独保证的，而是由主键、唯一键、外键、检查约束、事务原子性、隔离性、持久性以及业务代码共同保证。例如账户余额不能小于 0，数据库可以用约束限制，业务也要在扣款前校验余额，并在并发扣款时用锁或条件更新避免超扣。</p><p>面试中可以说：AID 是数据库更偏底层的保障，C 是最终目标。数据库提供机制，但业务规则仍需要应用正确建模。</p><h3 id="_3-隔离性-并发事务之间看见什么" tabindex="-1">3. 隔离性：并发事务之间看见什么 <a class="header-anchor" href="#_3-隔离性-并发事务之间看见什么" aria-label="Permalink to &quot;3\\. 隔离性：并发事务之间看见什么&quot;">​</a></h3><p>隔离性控制多个事务并发执行时彼此可见的程度。隔离越强，异常读越少，但并发性能通常越低；隔离越弱，读写阻塞更少，但业务需要承担更多一致性风险。MySQL 常见隔离级别从弱到强是读未提交、读已提交、可重复读、串行化。</p><h3 id="_4-持久性-提交后的结果能够恢复" tabindex="-1">4. 持久性：提交后的结果能够恢复 <a class="header-anchor" href="#_4-持久性-提交后的结果能够恢复" aria-label="Permalink to &quot;4\\. 持久性：提交后的结果能够恢复&quot;">​</a></h3><p>持久性要求事务提交后，即使数据库崩溃，结果也不能丢。InnoDB 主要通过 redo log 保证这一点。数据页可以稍后刷盘，但 redo 必须在提交路径上形成可恢复依据。刷盘参数会影响持久性强度和性能，因此不能脱离业务场景单独讨论。</p><h2 id="三、并发事务的典型问题" tabindex="-1">三、并发事务的典型问题 <a class="header-anchor" href="#三、并发事务的典型问题" aria-label="Permalink to &quot;三、并发事务的典型问题&quot;">​</a></h2><p>并发事务的问题，本质上是“一个事务读到另一个事务的中间状态或后续变化”。面试里最常考脏读、不可重复读和幻读，三者关注点不同。</p><p><img src="'+d+'" alt="images/mysql-transaction-isolation-case.png"></p><p>images/mysql-transaction-isolation-case.png</p><p>这张旧图把两个事务的执行顺序横向排开，适合用来观察“读到未提交”“同一行前后变化”“范围内多出记录”这些现象分别发生在什么时候。看隔离级别时，先看现象，再记表格，会比只背定义更稳。</p><h3 id="_1-脏读-读到未提交数据" tabindex="-1">1. 脏读：读到未提交数据 <a class="header-anchor" href="#_1-脏读-读到未提交数据" aria-label="Permalink to &quot;1\\. 脏读：读到未提交数据&quot;">​</a></h3><p>脏读是指事务 A 读到了事务 B 尚未提交的修改。如果事务 B 随后回滚，事务 A 读到的就是从未真正生效的数据。脏读破坏性很强，通常只可能出现在读未提交隔离级别中。大多数生产系统不会使用这个隔离级别。</p><h3 id="_2-不可重复读-同一行两次读到不同值" tabindex="-1">2. 不可重复读：同一行两次读到不同值 <a class="header-anchor" href="#_2-不可重复读-同一行两次读到不同值" aria-label="Permalink to &quot;2\\. 不可重复读：同一行两次读到不同值&quot;">​</a></h3><p>不可重复读是指同一事务内，两次读取同一行，结果不一致。原因通常是另一个事务在两次读取之间修改并提交了这行数据。它关注的是“同一行内容发生变化”。在读已提交隔离级别下，每次一致性读都会生成新的 Read View，因此可能读到其他事务刚提交的新版本。</p><h3 id="_3-幻读-同一范围两次读到不同记录集合" tabindex="-1">3. 幻读：同一范围两次读到不同记录集合 <a class="header-anchor" href="#_3-幻读-同一范围两次读到不同记录集合" aria-label="Permalink to &quot;3\\. 幻读：同一范围两次读到不同记录集合&quot;">​</a></h3><p>幻读是指同一事务内，两次按相同条件查询一个范围，记录集合发生变化，例如第二次多出一条符合条件的新记录。它关注的是“范围内记录数量变化”。在 InnoDB 可重复读下，普通快照读通过 MVCC 可以避免大多数幻读感受；当前读和范围写则需要 next-key lock 锁住记录和间隙，阻止其他事务插入造成范围变化。</p><h2 id="四、四种隔离级别的语义" tabindex="-1">四、四种隔离级别的语义 <a class="header-anchor" href="#四、四种隔离级别的语义" aria-label="Permalink to &quot;四、四种隔离级别的语义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>隔离级别</th><th>可见性特点</th><th>可能问题</th><th>常见使用边界</th></tr></thead><tbody><tr><td>READ UNCOMMITTED</td><td>可以读到未提交修改</td><td>脏读、不可重复读、幻读</td><td>很少用于核心业务</td></tr><tr><td>READ COMMITTED</td><td>每条语句读取已提交版本</td><td>不可重复读、幻读</td><td>Oracle 默认，MySQL 也常用于降低锁冲突</td></tr><tr><td>REPEATABLE READ</td><td>同一事务快照读保持一致</td><td>当前读仍需锁处理幻读</td><td>InnoDB 默认隔离级别</td></tr><tr><td>SERIALIZABLE</td><td>事务尽量串行执行</td><td>并发性能差</td><td>极少数强隔离场景</td></tr></tbody></table><p>读已提交和可重复读的差异，要抓住 Read View 的生成时机。RC 下每次普通查询都会生成新的 Read View，因此同一事务后续查询能看到其他事务新提交的数据；RR 下通常在第一次快照读时生成 Read View，后续快照读复用它，因此同一事务内看到的版本更稳定。</p><p>串行化不是性能优化手段，而是用并发退让换取更强隔离。大多数 Java 后端项目不会默认使用串行化，而是依赖合理事务范围、索引、锁、唯一约束和业务幂等来保证正确性。</p><h2 id="五、read-view-与-mvcc-可见性判断" tabindex="-1">五、Read View 与 MVCC 可见性判断 <a class="header-anchor" href="#五、read-view-与-mvcc-可见性判断" aria-label="Permalink to &quot;五、Read View 与 MVCC 可见性判断&quot;">​</a></h2><p>MVCC（Multi-Version Concurrency Control，多版本并发控制）让读操作不必总是等待写锁。InnoDB 行记录中包含隐藏事务 ID 和回滚指针。事务修改一行时，会生成新版本，并通过 undo log 保留旧版本。普通一致性读根据 Read View 判断当前版本是否可见，不可见就沿 undo 版本链找更旧版本。</p><p>Read View 可以理解为事务拍下的一张“活跃事务快照”。它通常包含当前活跃事务 ID 列表、最小活跃事务 ID、下一个将分配的事务 ID 等信息。判断规则可以简化为：由当前事务自己修改的版本可见；比快照中最小活跃事务还早的已提交版本可见；大于等于下一个事务 ID 的未来版本不可见；处在活跃事务列表中的版本不可见。</p><p>这个机制解释了为什么快照读不一定读最新数据。它读的是“对当前事务可见的最新版本”。因此在同一个事务中，普通 SELECT 可能看到旧版本，而 SELECT ... FOR UPDATE、UPDATE、DELETE 这类当前读必须读最新版本，并会加锁。</p><h2 id="六、rr-下为什么还要-next-key-lock" tabindex="-1">六、RR 下为什么还要 next-key lock <a class="header-anchor" href="#六、rr-下为什么还要-next-key-lock" aria-label="Permalink to &quot;六、RR 下为什么还要 next-key lock&quot;">​</a></h2><p>很多面试题会问：InnoDB 默认可重复读不是已经有 MVCC 了吗，为什么还需要间隙锁和临键锁？原因在于 MVCC 主要解决普通快照读的可见性，而当前读和写操作要面对真实的最新数据。如果事务要对一个范围执行 SELECT ... FOR UPDATE 或 UPDATE where age between 10 and 20，只锁住已有记录并不够，其他事务仍可能在范围间隙插入新记录，导致当前事务后续再次范围当前读时出现新行。</p><p>next-key lock 可以理解为 record lock 加 gap lock。record lock 锁住已存在的索引记录，gap lock 锁住索引记录之间的间隙，next-key lock 同时保护记录和记录前的间隙。InnoDB 在 RR 下对很多范围当前读使用 next-key lock，就是为了阻止其他事务在被保护范围内插入新记录，从而减少幻读。</p><p>这里还要补一句边界：如果查询使用唯一索引等值命中一条唯一记录，InnoDB 可能把 next-key lock 优化为 record lock，因为不存在需要保护的范围间隙。锁范围一定要结合隔离级别、索引类型、查询条件和读类型一起分析。</p><h2 id="七、事务使用边界" tabindex="-1">七、事务使用边界 <a class="header-anchor" href="#七、事务使用边界" aria-label="Permalink to &quot;七、事务使用边界&quot;">​</a></h2><p>事务不是越大越安全。长事务会持有锁更久，占用 undo 版本，拖慢 purge，增加死锁概率，还可能让主从复制延迟扩大。Java 后端中常见问题包括：在事务中调用外部接口、把用户交互或远程 RPC 放进事务、一次事务批量处理过多数据、事务方法里混入耗时计算。</p><p>比较稳妥的原则是：事务只包住必须原子提交的数据库操作，尽量短、尽量明确；外部调用放在事务外或通过本地消息表、可靠事件、补偿机制解耦；高并发扣减场景优先使用条件更新、唯一约束、乐观锁或明确的行锁，而不是把大段业务逻辑都塞进一个事务。</p><h2 id="八、面试表达模板" tabindex="-1">八、面试表达模板 <a class="header-anchor" href="#八、面试表达模板" aria-label="Permalink to &quot;八、面试表达模板&quot;">​</a></h2><p>如果被问“ACID 如何实现”，可以答：原子性主要依赖 undo log 回滚，持久性主要依赖 redo log 崩溃恢复，隔离性依赖 MVCC 和锁共同实现，一致性是最终目标，由数据库约束、AID 机制和业务规则共同保证。</p><p>如果被问“RC 和 RR 的区别”，可以答：核心区别是 Read View 生成时机。RC 每次快照读都会生成新的 Read View，因此能读到其他事务新提交的数据；RR 通常在第一次快照读时生成 Read View，后续复用，所以同一事务内快照读结果稳定。InnoDB RR 对范围当前读还会结合 next-key lock 降低幻读风险。</p><p>如果被问“幻读怎么解决”，可以答：普通快照读通过 MVCC 让同一事务看到稳定版本；当前读或范围写需要依赖锁，尤其是 next-key lock 锁住记录和间隙，阻止其他事务在范围内插入新记录。回答时要区分快照读和当前读。</p><h2 id="九、常见追问与练习" tabindex="-1">九、常见追问与练习 <a class="header-anchor" href="#九、常见追问与练习" aria-label="Permalink to &quot;九、常见追问与练习&quot;">​</a></h2><p><strong>追问 1：普通 SELECT 会加锁吗？</strong> 在 InnoDB 默认情况下，普通一致性读通常不加锁，而是通过 MVCC 读取可见版本。SELECT ... FOR UPDATE、SELECT ... FOR SHARE、UPDATE、DELETE 属于当前读，才会读取最新版本并加锁。</p><p><strong>追问 2：为什么可重复读下仍然可能讨论幻读？</strong> 因为要区分快照读和当前读。RR 下普通快照读通常能看到稳定结果，但范围当前读和写操作必须面对最新数据，需要 next-key lock 来阻止插入型幻读。</p><p><strong>练习 1：事务 T1 在 RC 下先查询 id=1 的余额为 100，T2 提交把余额改为 80，T1 再查同一行看到多少？为什么？</strong> 答案：通常会看到 80。RC 下每次快照读生成新的 Read View，第二次查询可以看到 T2 已提交的新版本，因此可能出现不可重复读。</p><p><strong>练习 2：事务中为什么不建议调用远程接口？</strong> 答案：远程接口耗时和失败都不可控，会延长事务时间，导致锁持有时间变长、undo 版本堆积、死锁概率上升。更好的做法是缩短数据库事务，把外部动作通过事件、消息或补偿流程解耦。</p>',56)])])}const b=e(i,[["render",l]]);export{u as __pageData,b as default};
